"""Render the latest result files into docs/EVALUATION_RESULTS.md (generated; do not edit by hand).

Usage: backend/.venv/Scripts/python experiments/report.py
"""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RES = ROOT / "experiments" / "results"
OUT = ROOT / "docs" / "EVALUATION_RESULTS.md"


def latest(kind: str) -> tuple[str, dict] | None:
    files = sorted(RES.glob(f"{kind}_2*.json"))
    if not files:
        return None
    return files[-1].name, json.loads(files[-1].read_text(encoding="utf-8"))


def pct(v) -> str:
    return "–" if v is None else f"{v * 100:.1f}%"


def ms(v) -> str:
    if v is None:
        return "–"
    return f"{v / 1000:.2f} s" if v >= 1000 else f"{v:.0f} ms" if v >= 10 else f"{v:.1f} ms"


def f3(v) -> str:
    return "–" if v is None else f"{v:.3f}"


def table(headers: list[str], rows: list[list[str]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(r) + " |" for r in rows]
    return "\n".join(out)


def main() -> None:
    parts = ["# Evaluation results (generated)", "",
             "_Generated by `experiments/report.py` from the newest files in `experiments/results/`. "
             "Methodology and interpretation: [EVALUATION.md](EVALUATION.md)._", ""]

    fw = latest("firewall_comparison")
    if fw:
        name, d = fw
        ds = d["dataset"]
        parts += [f"## Firewall comparison", "", f"`{name}` · dataset `{ds['name']}` ({ds['split']}, sha256 `{ds['sha256'][:12]}…`) · "
                  f"{ds['n_samples']} samples ({ds['n_attack']} attack / {ds['n_benign']} non-attack) · requests evaluated as cloud-bound", ""]
        rows = []
        for c in d["configs"]:
            m = c["metrics"]
            rows.append([c["name"], pct(m["precision"]), pct(m["recall"]), f3(m["f1"]), pct(m["fpr"]), pct(m["asr"]),
                         pct(m["policy_violation_rate"]), pct(m["over_enforcement_rate"]), pct(m.get("pii_redaction_success")),
                         ms(m["p50_ms"]), ms(m["p95_ms"]), ms(m["p99_ms"]), str(m["verifier_calls"])])
        parts += [table(["Config", "Precision", "Recall", "F1", "FPR", "ASR", "Policy viol.", "Over-enf.", "PII redaction",
                         "P50", "P95", "P99", "Verifier calls"], rows), ""]
        rows = [[c["name"]] + [pct(c["metrics_unseen_sources"][k]) if k != "f1" else f3(c["metrics_unseen_sources"][k])
                               for k in ("precision", "recall", "f1", "fpr", "asr")] for c in d["configs"] if c["mode"]]
        parts += ["Unseen sources only (excluding `seen_risk` sources):", "",
                  table(["Config", "Precision", "Recall", "F1", "FPR", "ASR"], rows), ""]
        cats = list(d["configs"][1]["by_category"].keys())
        rows = []
        for cat in cats:
            info = d["configs"][1]["by_category"][cat]
            rows.append([f"{cat} ({info['n']}, {info['label']})"] + [pct(c["by_category"][cat]["block_rate"]) for c in d["configs"] if c["mode"]])
        parts += ["Block rate by category (recall for attack categories, false-positive rate for benign ones):", "",
                  table(["Category"] + [c["name"] for c in d["configs"] if c["mode"]], rows), ""]
        srcs = list(d["configs"][1]["by_source"].keys())
        rows = [[f"{s} ({d['configs'][1]['by_source'][s]['n']}, {d['configs'][1]['by_source'][s]['label']})"]
                + [pct(c["by_source"][s]["block_rate"]) for c in d["configs"] if c["mode"]] for s in srcs]
        parts += ["Block rate by source:", "", table(["Source"] + [c["name"] for c in d["configs"] if c["mode"]], rows), ""]
        llm = d.get("llm_attack_success")
        if llm:
            fails = sorted({s["family"] for s in llm["samples"] if s["firewall_success"]})
            parts += [f"**LLM-in-the-loop attack success** ({llm['n']} canary attacks, model `{llm['model']}`): "
                      f"{pct(llm['asr_no_firewall'])} without the firewall, {pct(llm['asr_with_firewall'])} with SentinelLLM (hybrid_verify). "
                      f"Families that still succeeded: {', '.join(fails) or 'none'}.", ""]

    de = latest("detector_eval")
    if de:
        name, d = de
        rows = []
        for r in d["rows"]:
            m = r["metrics"]
            if r["detector"] == "pii":
                continue
            rows.append([r["detector"], r["mode"], str(r["n"]), pct(m.get("precision")), pct(m.get("recall")), f3(m.get("f1")), pct(m.get("fpr"))])
        parts += ["## Per-detector evaluation", "", f"`{name}` · thresholds {d['thresholds']}", "",
                  table(["Detector", "Mode", "n", "Precision", "Recall", "F1", "FPR"], rows), ""]

    pii = latest("detector_eval_pii")
    if pii:
        name, d = pii
        rows = []
        for k, v in d["results"].items():
            rows.append([k, pct(v["value_recall"]), str(v["values"]), "; ".join(f"{t} {x}" for t, x in v["recall_by_type"].items()),
                         f"{v['false_entities_per_benign_prompt']:.2f}"])
        parts += ["## PII detection (value-level)", "", f"`{name}`", "",
                  table(["Split / engine", "Value recall", "Values", "Recall by type", "False entities / benign prompt"], rows), ""]

    lat = latest("latency_benchmark")
    if lat:
        name, d = lat
        rows = [[k, str(v["n"]), ms(v["mean_ms"]), ms(v["p50_ms"]), ms(v["p95_ms"]), ms(v["p99_ms"])] for k, v in d["stats"].items()]
        parts += ["## Latency", "", f"`{name}` · {d['samples']} samples · {d['detectors_run']}", "",
                  table(["Stage", "n", "Mean", "P50", "P95", "P99"], rows), "",
                  table(["Input length", "n", "Mean", "P50", "P95", "P99"],
                        [[k, str(v["n"]), ms(v["mean_ms"]), ms(v["p50_ms"]), ms(v["p95_ms"]), ms(v["p99_ms"])] for k, v in sorted(d["pipeline_by_length"].items())]), ""]

    for kind in ("experiment_context_aware", "experiment_selective_verification", "experiment_hybrid"):
        ex = latest(kind)
        if not ex:
            continue
        name, d = ex
        cols = d["columns"]

        def fmt(c: str, v) -> str:
            if not isinstance(v, (int, float)):
                return str(v)
            if c.endswith("_ms"):
                return ms(v)
            if c.startswith("n_") or c.endswith("_calls") or c.endswith("_tokens"):
                return f"{v:,}"
            if c.startswith("est_cost"):
                return f"${v:.4f}"
            if c == "f1":
                return f3(v)
            return pct(v)

        rows = [[c["name"]] + [fmt(k, c["metrics"].get(k)) for k in cols] for c in d["configs"]]
        parts += [f"## {d['title']}", "", f"`{name}` · {d['description']}", "", table(["Config"] + cols, rows), ""]

    acc = latest("acceptance")
    if acc:
        name, d = acc
        rows = [[str(r["test"]), r["name"], r["status"], r["detail"].replace("|", "/")] for r in d["results"]]
        parts += ["## Acceptance tests", "", f"`{name}` · target `{d['target']}` · {d['summary']}", "",
                  table(["#", "Test", "Status", "Detail"], rows), ""]

    OUT.write_text("\n".join(parts), encoding="utf-8")
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
